    for (const [x, y] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) { const d = M([[x * W2 / 2 - 8, y * H2 / 2 - 8], [x * W2 / 2 + 8, y * H2 / 2 - 8], [x * W2 / 2 + 8, y * H2 / 2 + 8], [x * W2 / 2 - 8, y * H2 / 2 + 8]]) + 'Z'; s += `<path d="${d}" class="fill-paper"/><path d="${d}" fill="url(#hx)"/>` + sk(d, 'ink thin'); }
