    for (let i = 0; i < 12; i++) { const a = rad(i * 30); s += `<path d="M${f(26 * Math.sin(a))} ${f(-26 * Math.cos(a))} L${f(46 * Math.sin(a))} ${f(-46 * Math.cos(a))}" class="ink hair"/>`; }
